using Agwinterm.Core;
using Agwinterm.Pty.Proto;

namespace Agwinterm.Pty;

// One transfer per attachment, serialized by the independent query channel.
// Partial imports never touch the terminal. No PTY input is generated by restore.
internal sealed class OwnerBufferTransfer(TerminalSession session)
{
    internal const int MaximumBytes=64*1024*1024, ChunkBytes=512*1024;
    private byte[]? _bytes;
    private int _received;
    private bool _import;
    private string _token="";
    public void Execute(PresentationQuery request,PresentationQueryReply reply)
    {
        reply.Status="invalid";
        switch(request.Operation)
        {
            case "buffer-export":
                lock(session.SyncRoot) _bytes=BufferPersist.Serialize(session.Emulator);
                if(_bytes.Length > MaximumBytes) { _bytes=null; return; }
                _import=false; _token=Guid.NewGuid().ToString("N");
                reply.Rows.Add(_token); reply.Rows.Add(_bytes.Length.ToString(System.Globalization.CultureInfo.InvariantCulture));
                break;
            case "buffer-read":
                if(_bytes is null || _import || request.Text != _token || request.StartRow < 0 || request.StartRow >= _bytes.Length) return;
                reply.Rows.Add(Convert.ToBase64String(_bytes,request.StartRow,Math.Min(ChunkBytes,_bytes.Length-request.StartRow)));
                break;
            case "buffer-import":
                if(request.StartRow is < 1 or > MaximumBytes) return;
                _bytes=new byte[request.StartRow]; _received=0; _import=true; _token=Guid.NewGuid().ToString("N");
                reply.Rows.Add(_token);
                break;
            case "buffer-write":
                if(_bytes is null || !_import || request.StartRow != _received || request.Text.Length > ChunkBytes*2) return;
                int separator=request.Text.IndexOf(':');
                if(separator != _token.Length || request.Text[..separator] != _token) return;
                byte[] chunk;
                try { chunk=Convert.FromBase64String(request.Text[(separator+1)..]); } catch(FormatException) { return; }
                if(chunk.Length is < 1 or > ChunkBytes || chunk.Length > _bytes.Length-_received) return;
                chunk.CopyTo(_bytes,_received); _received+=chunk.Length;
                break;
            case "buffer-commit":
                if(_bytes is null || !_import || request.Text != _token || _received != _bytes.Length ||
                    !BufferPersist.TryParse(_bytes,out var buffer)) return;
                // Clear transfer authority before mutation: a retry cannot append twice.
                _bytes=null; _token="";
                session.MutateLocked(core=>BufferPersist.Restore(core,buffer));
                break;
            case "buffer-release":
                if(request.Text != _token) return;
                _bytes=null; _token="";
                break;
            default: return;
        }
        reply.Status="ok";
    }
}
